export function comparisonVerdict(value) {
 return ({violation:'Recorded overlap found',clear:'No recorded overlap · identity confirmed',clear_pending_confirmation:'No recorded overlap · identity needs confirmation',insufficient:'Insufficient evidence',incomplete:'Check incomplete'})[value]||'No supported verdict';
}

export function comparisonNotice(c) {
 const legacy=c.schema_version!==2;
 const comparable=!legacy&&c.identity_membership_comparable===true;
 return {
  heading:legacy?'Earlier comparison · identity and membership only':comparable?'Same samples and identities; compare partition membership.':'Identity or evaluation scope differs between receipts.',
  note:legacy?'This older comparison did not check whether other fields changed. Its partition-only flag is not a guarantee of unchanged features.':
   'Other input fields may differ. Inspect changed files before attributing a result to the split change.'
 };
}

